package item

props {
  // Variant sets the surface: Default, Outline or Muted.
  Variant  Variant = Default
  // Size sets the padding and the gap: Md or Sm.
  Size     Size = Md
  // Href is the link target. With a value the root is an a element; empty gives a div.
  Href     gx.URL = ""
  // Class adds classes to the root element.
  Class    string = ""
  // Children is the content of the item.
  Children gx.Node
  // Attrs adds HTML attributes to the root element.
  Attrs    gx.Attrs = nil
}

if p.Href != "" {
  <a href={p.Href} data-slot="item" data-variant={p.variant()} data-size={p.size()} class={p.class()} {...p.Attrs}>{p.Children}</a>
} else {
  <div data-slot="item" data-variant={p.variant()} data-size={p.size()} class={p.class()} {...p.Attrs}>{p.Children}</div>
}

